// ==========================================================
// ⚙️ GŁÓWNA KONFIGURACJA AUDYTU WORKFLOW
// ==========================================================

const baseUrl = 'http://localhost:5678';
const retentionDays = 90;
const dataTableName = 'Audyt Workflow - Dzienne Uruchomienia';
// Bezpiecznik paginacji: maks. liczba stron (po 250 rekordów) na pętlę
const maxPages = 400;
// Backfill: wpisz datę 'yyyy-MM-dd', aby audytować konkretny dzień. Puste = wczoraj.
const targetDateOverride = '';

let targetDateObj;
if (targetDateOverride) {
  targetDateObj = /^\d{4}-\d{2}-\d{2}$/.test(targetDateOverride)
    ? DateTime.fromFormat(targetDateOverride, 'yyyy-MM-dd', { zone: 'Europe/Warsaw' })
    : null;
  if (!targetDateObj || !targetDateObj.isValid) {
    throw new Error(`[Audyt] Niepoprawna data targetDateOverride: '${targetDateOverride}' (oczekiwano istniejącej daty yyyy-MM-dd).`);
  }
  if (targetDateObj.startOf('day') >= DateTime.now().setZone('Europe/Warsaw').startOf('day')) {
    throw new Error(`[Audyt] targetDateOverride '${targetDateOverride}' musi być dniem z przeszłości.`);
  }
} else {
  targetDateObj = DateTime.now().setZone('Europe/Warsaw').minus({ days: 1 });
}

const targetDate = targetDateObj.toFormat('yyyy-MM-dd');
const executionsStartedAfter = targetDateObj.startOf('day').toUTC().toISO();
const executionsStartedBefore = targetDateObj.endOf('day').toUTC().toISO();

return [{
  json: {
    baseUrl: baseUrl,
    retentionDays: retentionDays,
    dataTableName: dataTableName,
    maxPages: maxPages,
    targetDate: targetDate,
    executionsStartedAfter: executionsStartedAfter,
    executionsStartedBefore: executionsStartedBefore
  }
}];

const input = $input.first()?.json || {};
const tableId = input.id;

if (!tableId) {
  throw new Error('[Audyt] Nie udało się ustalić ID tabeli w Data Tables.');
}

return [{ json: { tableId: String(tableId) } }];

const resp = $input.first()?.json || {};
const list = Array.isArray(resp.data) ? resp.data : (Array.isArray(resp) ? resp : []);
const nextCursor = resp.nextCursor || null;
const selfId = String($workflow.id);
const maxPages = Number($('⚙️ Konfiguracja').first()?.json?.maxPages) || 400;

let map = {};
let page = 1;
let prevCursor = null;
try {
  const prev = $('Kolejny Kursor Workflows').last()?.json;
  if (prev && prev.workflowMap && typeof prev.workflowMap === 'object') {
    map = { ...prev.workflowMap };
    page = (Number(prev.page) || 0) + 1;
    prevCursor = prev.cursor || null;
  }
} catch (e) {}

// Bezpiecznik paginacji
if (nextCursor && nextCursor === prevCursor) {
  throw new Error(`[Audyt] API workflows zwróciło ten sam kursor ponownie (strona ${page}) – przerwano, by uniknąć nieskończonej pętli.`);
}
if (nextCursor && page >= maxPages) {
  throw new Error(`[Audyt] Przekroczono limit ${maxPages} stron workflows – zwiększ maxPages w Konfiguracji.`);
}

for (const wf of list) {
  if (!wf || !wf.id || String(wf.id) === selfId) continue;
  map[String(wf.id)] = {
    name: String(wf.name || ''),
    active: Boolean(wf.active)
  };
}

return [{
  json: {
    workflowMap: map,
    page: page,
    nextCursor: nextCursor,
    hasMore: Boolean(nextCursor)
  }
}];

const curr = $input.first()?.json || {};
return [{
  json: {
    cursor: curr.nextCursor,
    page: curr.page,
    workflowMap: curr.workflowMap
  }
}];

const cfg = $('⚙️ Konfiguracja').first()?.json || {};
const resp = $input.first()?.json || {};
const list = Array.isArray(resp.data) ? resp.data : (Array.isArray(resp) ? resp : []);
const nextCursor = resp.nextCursor || null;
const selfId = String($workflow.id);
const maxPages = Number(cfg.maxPages) || 400;

// Zakres filtrowany już przez API (startedAfter/startedBefore) - tu tylko zabezpieczenie.
const rangeStart = new Date(cfg.executionsStartedAfter).getTime();
const rangeEnd = new Date(cfg.executionsStartedBefore).getTime();

let counts = {};
let totalProcessed = 0;
let page = 1;
let prevCursor = null;
try {
  const prev = $('Kolejny Kursor Egzekucji').last()?.json;
  if (prev && prev.dailyCounts) {
    counts = { ...prev.dailyCounts };
    totalProcessed = Number(prev.totalProcessed) || 0;
    page = (Number(prev.page) || 0) + 1;
    prevCursor = prev.cursor || null;
  }
} catch (e) {}

// Bezpiecznik paginacji
if (nextCursor && nextCursor === prevCursor) {
  throw new Error(`[Audyt] API egzekucji zwróciło ten sam kursor ponownie (strona ${page}) – przerwano, by uniknąć nieskończonej pętli.`);
}
if (nextCursor && page >= maxPages) {
  throw new Error(`[Audyt] Przekroczono limit ${maxPages} stron egzekucji – zwiększ maxPages w Konfiguracji.`);
}

for (const e of list) {
  if (!e || !e.workflowId) continue;
  const ts = new Date(e.startedAt || e.createdAt || 0).getTime();
  if (ts < rangeStart || ts > rangeEnd) continue;

  const wfId = String(e.workflowId);
  if (wfId === selfId) continue;

  if (!counts[wfId]) {
    counts[wfId] = { total: 0, success: 0 };
  }
  counts[wfId].total++;
  if (e.status === 'success') {
    counts[wfId].success++;
  }
  totalProcessed++;
}

return [{
  json: {
    dailyCounts: counts,
    totalProcessed: totalProcessed,
    page: page,
    nextCursor: nextCursor,
    hasMore: Boolean(nextCursor)
  }
}];

const curr = $input.first()?.json || {};
return [{
  json: {
    cursor: curr.nextCursor,
    page: curr.page,
    dailyCounts: curr.dailyCounts,
    totalProcessed: curr.totalProcessed
  }
}];

const cfg = $('⚙️ Konfiguracja').first()?.json || {};
const targetDate = cfg.targetDate;
const wfState = $('Zbierz i Oceń Workflows').last()?.json || {};
const wfMap = wfState.workflowMap || {};
const execState = $('Agreguj i Oceń Egzekucje').last()?.json || {};
const counts = execState.dailyCounts || {};
const selfId = String($workflow.id);

const allIds = new Set([...Object.keys(wfMap), ...Object.keys(counts)]);
const results = [];

for (const wfId of allIds) {
  if (wfId === selfId) continue;
  const meta = wfMap[wfId] || { name: `[Workflow Usunięty] (${wfId})`, active: false };
  const c = counts[wfId] || { total: 0, success: 0 };

  results.push({
    json: {
      date: targetDate,
      workflow_id: wfId,
      workflow_name: meta.name,
      daily_executions: c.total,
      daily_success_count: c.success,
      is_active: Boolean(meta.active)
    }
  });
}

return results;

// Pobierz wszystkie zapisane wiersze
const savedRows = $input.all();

const cfg = $('⚙️ Konfiguracja').first()?.json || {};
const tableId = $('Ustal Table ID').first()?.json?.tableId;
const execState = $('Agreguj i Oceń Egzekucje').last()?.json || {};

const targetDate = cfg.targetDate || '';
const retentionDays = Number(cfg.retentionDays) || 90;
const cutoff = DateTime.now().setZone('Europe/Warsaw').minus({ days: retentionDays }).startOf('day');

// Zwracamy DOKŁADNIE JEDEN element z parametrami retencji i raportu
return [{
  json: {
    tableId: String(tableId),
    targetDate: targetDate,
    retentionBeforeDate: cutoff.toFormat('yyyy-MM-dd'),
    retentionBeforeISO: cutoff.toUTC().toISO(),
    workflowsTracked: savedRows.length,
    totalExecutions: Number(execState.totalProcessed) || 0,
    timestamp: DateTime.now().setZone('Europe/Warsaw').toISO()
  }
}];

// Pobieramy dane raportu z bezpośrednio poprzedzającego węzła agregacji
const report = $('Agreguj Raport i Przygotuj Retencję').first()?.json || {};

return [{
  json: {
    success: true,
    message: 'Audyt dziennych uruchomień zakończony pomyślnie',
    auditedDate: report.targetDate,
    workflowsTracked: report.workflowsTracked || 0,
    totalExecutions: report.totalExecutions || 0,
    retentionPurgedBefore: report.retentionBeforeDate,
    timestamp: report.timestamp || DateTime.now().setZone('Europe/Warsaw').toISO()
  }
}];

// Wyczyść Istniejące Wpisy z Dnia zwraca usunięte wiersze - do zapisu przekazujemy
// świeżo skomponowane wyniki, nie wyjście z kasowania.
return $('Skomponuj Wyniki').all();
